let xsp = 0;
let ysp = 0;
let mxsp = 0;
let mysp = 0;
let gx = 0; 
let gy = 0;
let sz = 50;
let frw = false;
let back = false;
let decel = false;
let bckgrnd;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  background(0);
  bckgrnd = new Background(0, 0);
}

function draw() {
  translate(gx,gy);
  fill(30, 200);
  noStroke();
  rect(-gx-50, -gy-50, width+100, height+100);
  if(decel){
    xsp = xsp/1.05;
    ysp = ysp/1.05;
  }
  bckgrnd.display();
  bckgrnd.update();
  bckgrnd.move(xsp, ysp);
  if(frw){
    if((-(width/2.0)+(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/65 < 20){
      mxsp = (-(width/2.0)+(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/65;
    }else{
      mxsp = 20;
    }
    if((-(height/2.0)+(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/65 < 20){
      mysp = (-(height/2.0)+(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/65;
    }else{
      mysp = 20;
    }
    if(ysp < mysp){
      ysp += 0.25;
    }else if(ysp > mysp){
      ysp -= 0.25;
    }
    if(xsp < mxsp){
      xsp += 0.25;
    }else if(xsp > mxsp){
      xsp -= 0.25;
    }
  }
  if(back){
    mxsp = ((width/2)-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/65;
    mysp = ((height/2)-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/65;
    if(ysp < mysp){
      ysp += 0.5;
    }else if(ysp > mysp){
      ysp -= 0.5;
    }
    if(ysp < mxsp){
      xsp += 0.5;
    }else if(ysp > mxsp){
      xsp -= 0.5;
    }
  }
  fill(200,255);
  noStroke();
  //ellipse(width/2-gx,height/2-gy,sz,sz);
}

