// === Tab: tab2 ===
class Background {

  x;
  y;
  pntsz = 2;
  traveled = 0;
  let dx = new Array(800);
  let dy = new Array(800);
  let mult = new Array(800);
  let colors = new Array(800);
  c1 = 205;
  c2 = 205;
  c3 = 205;

  constructor(px, py) {
    x = px;
    y = py;
    for (i = 0; i < dx.length; i ++) {
      dx[i] = random(-100, width+100);
      dy[i] = random(-100, height+100);
      mult[i] = random(0, 2.1);
      colors[i] = color(255);
    }
  }

  function display() {
    for (i = 0; i < dx.length; i ++) {
      fill(colors[i]);
      stroke(colors[i]);
      strokeWeight(pntsz*(mult[i]*2));
      point(dx[i], dy[i]);
    }
  }

  function update() {
    for (i = 0; i < dx.length; i ++) {
      if (dx[i] < -100-gx) {
        dx[i] = random(width+50-gx, width+100-gx);
        traveled ++;
        if (traveled%500 == 0) {
          for (b = 0; b < colors.length; b ++) {
            c1 = random(50, 205);
            c2 = random(50, 205);
            c3 = random(50, 205);
            //colors[b] = color(random(255), random(255), random(255));
          }
        }
        if (traveled >= 3000) {
          colors[i] = color(c1+random(-50, 50), c2+random(-50, 50), c3+random(-50, 50));
        }
      }
      if (dx[i] > width+100-gx) {
        dx[i] = random(-100-gx, -50-gx);
        traveled ++;
        if (traveled >= 3000) {
          colors[i] = color(c1+random(-50, 50), c2+random(-50, 50), c3+random(-50, 50));
        }
      }
      if (dy[i] < -100-gy) {
        dy[i] = random(height+50-gy, height+100-gy);
        traveled ++;
        if (traveled >= 3000) {
          colors[i] = color(c1+random(-50, 50), c2+random(-50, 50), c3+random(-50, 50));
        }
      }
      if (dy[i] > height+100-gy) {
        dy[i] = random(-100-gy, -50-gy);
        traveled ++;
        if (traveled >= 3000) {
          colors[i] = color(c1+random(-50, 50), c2+random(-50, 50), c3+random(-50, 50));
        }
      }
    }

    /* for (i = 0; i < dx.length; i ++) {
     if (dist(width/2-gx, height/2-gy,dx[i],dy[i]) < sz/2){
     sz += 0.5;
     if(random(10) <= 5){
     dx[i] = random(width+50-gx,width+100-gx);
     }else{
     dx[i] = random(-100-gx,-50-gx);
     }
     if(random(10) <= 5){
     dy[i] = random(height+50-gy,height+100-gy);
     }else{
     dy[i] = random(-100-gy,-50-gy);
     }
     }
     }*/
  }

  function move(mx, my) {
    gx -= mx;
    gy -= my;
    for (i = 0; i < dx.length; i ++) {
      dx[i] -= (mx)*mult[i];
      dy[i] -= (my)*mult[i];
    }
  }
}

